package com.zamcan.madrassa.domain.salah;
import java.util.Arrays;import java.util.Collections;import java.util.List;
/** Canonical wording for TTS or future licensed adhan audio. */
public final class AdhanScript{private AdhanScript(){}public static List<String> adhanLines(){return Collections.unmodifiableList(Arrays.asList("Allahu Akbar, Allahu Akbar","Allahu Akbar, Allahu Akbar","Ashhadu alla ilaha illallah","Ashhadu alla ilaha illallah","Ashhadu anna Muhammadan Rasulullah","Ashhadu anna Muhammadan Rasulullah","Hayya 'alas-salah","Hayya 'alas-salah","Hayya 'alal-falah","Hayya 'alal-falah","Allahu Akbar, Allahu Akbar","La ilaha illallah"));}public static List<String> fajrAdhanAddition(){return Collections.unmodifiableList(Arrays.asList("As-salatu khayrun minan-nawm","As-salatu khayrun minan-nawm"));}public static List<String> iqamaLines(){return Collections.unmodifiableList(Arrays.asList("Allahu Akbar, Allahu Akbar","Ashhadu alla ilaha illallah","Ashhadu anna Muhammadan Rasulullah","Hayya 'alas-salah","Hayya 'alal-falah","Qad qamatis-salah","Qad qamatis-salah","Allahu Akbar, Allahu Akbar","La ilaha illallah"));}}
